const mongoose = require('mongoose');

const vocabSchema = new mongoose.Schema({
  user_id: { type: String, required: true, index: true },
  language: { type: String, required: true, enum: ['en', 'ko', 'ja', 'zh', 'es', 'fr', 'vi'] },

  // Card content
  front: { type: String, required: true },
  back: { type: String, required: true },
  pronunciation: { type: String },
  example_sentences: [{ type: String }],

  // AI-enhanced card content (generated by enhance-queue)
  // Format uses [ko: ...] [vn: ...] [ex_ko: ...] [ex_vn: ...] tags for TTS routing
  ai_front:       { type: String },
  ai_back:        { type: String },
  ai_card_type:   { type: String, enum: ['vocab', 'grammar', 'phrase'] },
  ai_enhanced_at: { type: Date },
  ai_provider:    { type: String },
  ai_model:       { type: String },
  memory_tip:     { type: String },
  tts_back:       { type: String },   // kịch bản đọc ngắn (scripts/build-tts-back.js); null = chưa xử lý
  tts_rule_v:     { type: Number },   // phiên bản quy tắc đã sinh tts_back
  tts_source:     { type: String },   // 'ai' khi do ai-fill-tts.js sinh (quy tắc không ghi đè)
  // Nghe thụ động (app iOS Player / mọi lần chấm): số lần nghe, số lần Khó/Quên — ưu tiên + lịch nghe lại trong /listen-queue
  listen: {
    count:   { type: Number, default: 0 },
    hard:    { type: Number, default: 0 },
    last_at: { type: Date },
    hard_at: { type: Date },
    stage:   { type: Number },   // listening schedule step (listen-log): 1 → 1 day, 2 → 3, 3 → 7, 4 → 16, 5 → 35, 6 → 60
    next_at: { type: Date },     // when /listen-queue brings it back as a review
  },
  synonyms:       [{ type: String }],  // Feature 23 — up to 3 synonyms in target language
  confusable_with: [{                  // Feature 24 — words that sound/look similar
    card_id: { type: mongoose.Schema.Types.ObjectId, ref: 'Vocab' },
    word:    { type: String },
    reason:  { type: String },         // 'same_pronunciation' | 'similar_sound'
  }],
  antonym:              { type: String },       // Feature 29 — single antonym in target language
  word_family:          [{ type: String }],     // Feature 30 — related word forms (same root)
  word_family_scheduled:{ type: Boolean, default: false }, // Feature 30 — already auto-queued

  // Anki metadata
  deck_name: { type: String, default: 'default' },
  tags: [{ type: String }],
  level: {
    type: String,
    enum: ['A1','A2','B1','B2','C1','C2','N5','N4','N3','N2','N1',
           'HSK1','HSK2','HSK3','HSK4','HSK5','HSK6','HSK7','HSK8','HSK9',
           'TOPIK1','TOPIK2','TOPIK3','TOPIK4','TOPIK5','TOPIK6','unknown'],
    default: 'unknown',
  },

  // SRS tracking
  correct_attempts: { type: Number, default: 0 },
  incorrect_attempts: { type: Number, default: 0 },
  last_review_at: { type: Date },
  next_review_at: { type: Date, default: Date.now },
  interval_days: { type: Number, default: 1 },
  ease_factor: { type: Number, default: 2.5 },

  // Status
  status: { type: String, default: 'active', enum: ['active', 'new', 'modified', 'removed', 'mastered'] },
  // 'curated' PHẢI có trong enum. Đo trên DB thật: 11.376 thẻ (19,6% của 58.188) đang có
  // source='curated', nhưng enum thiếu giá trị đó — nên mongoose chặn ngay lúc save:
  //     ValidationError: Vocab validation failed: source: `curated` is not a valid enum value
  // Hệ quả là MỌI lần ôn 11.376 thẻ đó đều trả HTTP 500 và SRS không ghi được gì, ở cả
  // extension, app mobile lẫn chỗ nào khác gọi POST /api/learntools/review — vì recordReview()
  // kết thúc bằng vocab.save(). Bắt được khi thử ôn thẻ thật từ Electron app.
  // Dữ liệu là nguồn đúng ở đây: 'curated' là thẻ do người soạn/nhập có chọn lọc, khác 'manual'.
  source: { type: String, default: 'manual', enum: ['anki', 'manual', 'curated', 'ai_generated', 'passive_audio', 'dictionary'] },

  created_at: { type: Date, default: Date.now },
  updated_at: { type: Date, default: Date.now },
});

vocabSchema.index({ user_id: 1, language: 1 });
vocabSchema.index({ user_id: 1, next_review_at: 1 });

vocabSchema.virtual('accuracy').get(function () {
  const total = this.correct_attempts + this.incorrect_attempts;
  return total === 0 ? null : this.correct_attempts / total;
});

module.exports = mongoose.model('Vocab', vocabSchema);
